"""Build task/run JSON from the selected completed FT-All environment recordings."""
import argparse,json,hashlib,shutil,time
from pathlib import Path
import h5py,numpy as np
from tokenizers import Tokenizer
from facts import load,save,sha,read,bddl_language,instruction,xml_info,native_entities,scene,inventory
from identifiers import Registry

def collect(project):
 project=Path(project);cfg=load(project/'config/project.json');assert cfg['current_stage']=='execution_inventory_only' and cfg['llm_enabled'] is False and cfg['create_safety_records'] is False;source=Path(cfg['source_results']).resolve();summary=load(source/'summary.json');rootmeta=load(source/'run_metadata.json');assert rootmeta['checkpoint']==cfg['expected_checkpoint'],'Wrong checkpoint'
 for suite,expected in cfg['expected_success_percent'].items():
  s=summary['per_suite'][suite];assert round(100*s['passed']/s['completed'],8)==expected,'Wrong suite results'
 tokenizer=Tokenizer.from_file(str(project/'evidence/tokenizer/tokenizer.json'));assert sha(project/'evidence/tokenizer/tokenizer.json')==rootmeta['checkpoint_files']['tokenizer.json']['sha256'];tasks=[];runs=[];registrations=[];sources={};instruction_diffs=[];prompt_issues=[];h5_annotation_hits=[];start=time.time()
 def ref(path):
  path=Path(path);key=str(path.relative_to(source));digest=sources.setdefault(key,{'sha256':sha(path),'bytes':path.stat().st_size});return {'source_relative_path':key,**digest}
 for suite in cfg['suites']:
  tdirs=sorted(p for p in (source/suite).glob('task_*') if p.is_dir())
  for td in tdirs:
   tm=load(td/'run_metadata.json');task_id=tm['task_configuration_id'];bddl=bddl_language((td/'task.bddl').read_text());assert sha(td/'task.bddl')==tm['bddl_sha256'];task_runs=[];instructions=[];sample_scene=None;sample_entities=None;sample_measurements=None;sample_phase=None;sample_evaluator=None;sample_run=None
   (project/'evidence/task_definitions').mkdir(parents=True,exist_ok=True);shutil.copyfile(td/'task.bddl',project/'evidence/task_definitions'/(task_id+'.bddl'))
   registrations.append(('task',task_id,{'suite':tm['task_suite'],'benchmark_task_id':tm['task_id'],'task_name':tm['task_name'],'bddl_sha256':tm['bddl_sha256']}))
   for ep in sorted(p for p in td.glob('episode_*') if p.is_dir()):
    m=load(ep/'metadata.json');ev=load(ep/'evaluation.json');complete=load(ep/'completion.json');integrity=load(ep/'integrity_manifest.json');sem=load(ep/'semantic_initial_conditions.json');phase=sem['phases']['before_first_action'];index=load(ep/'simulator_index.json');xml=xml_info(ep/'simulator.xml');evaluator=load(ep/'evaluator_version.json');run_id=m['global_episode_id'];assert m['task_configuration_id']==task_id and ev['global_episode_id']==run_id and sem['global_episode_id']==run_id and complete['global_episode_id']==run_id;assert complete['complete'] and ev['error'] is None
    entities=native_entities(phase,index,xml);assert all(e['body_id'] is not None for e in entities),'Missing native body binding';this_scene=scene(phase,xml)
    with h5py.File(ep/'trajectory.h5','r') as h:
     assert h.attrs['global_episode_id']==run_id and h.attrs['task_configuration_id']==task_id;assert len(h['transitions'])==ev['steps']==len(h['policy_steps']);recorded=read(h['language_inputs/instruction']) if 'language_inputs/instruction' in h else m.get('instruction');ins=instruction(recorded,bddl);ins['evidence']={'source':'trajectory.h5','hdf5_path':'/language_inputs/instruction'} if 'language_inputs/instruction' in h else {'source':'metadata.json','json_pointer':'/instruction'}
     if recorded is not None and m.get('instruction') is not None:assert recorded==m['instruction'],'Conflicting instruction logs'
     bad=[];prompts=set()
     for name,g in h['inference_calls'].items():
      if 'processed_inputs/input_ids/value' not in g:bad.append({'inference_call':name,'issue':'No input IDs'});continue
      ids=g['processed_inputs/input_ids/value'][()].reshape(-1).tolist();prompt=tokenizer.decode(ids,skip_special_tokens=False);prompts.add(prompt)
      if recorded is not None and recorded not in prompt:bad.append({'inference_call':name,'issue':'Exact recorded instruction not present in decoded prompt','decoded_prompt':prompt})
     ins['prompt_token_check']={'inference_calls_checked':len(h['inference_calls']),'exact_instruction_in_all_decoded_prompts':not bad,'issues':bad,'decoded_prompt_variants':sorted(prompts),'tokenizer_sha256':rootmeta['checkpoint_files']['tokenizer.json']['sha256']}
     if bad:prompt_issues.append({'run_id':run_id,'issues':bad})
     available=inventory(h,ep,xml);frames=sorted(h['frames']);control_frames=[n for n in frames[:20] if str(h['frames'][n].attrs['stage']) in ['control','terminal']];offset=int(control_frames[0]) if control_frames else None
     if offset is not None:assert int(h['frames'][control_frames[0]].attrs['control_step'])==0 and int(h['frames'][frames[-1]].attrs['control_step'])==ev['steps']-1 and len(frames)==ev['steps']+offset
     keys=['requirement_id','case_id','claim_id','event_id','objection_id','safety_cases','safety_events']
     found=set(keys).intersection(set(h)|set(h.attrs))
     if found:h5_annotation_hits.append({'run_id':run_id,'keys':sorted(found)})
    for n in ['metadata.json','semantic_initial_conditions.json','simulator_index.json','simulator.xml','evaluator_version.json','evaluation.json']:
     evidence=ref(ep/n)
     if n in integrity['files']:assert evidence['sha256']==integrity['files'][n]['sha256'],'Changed source artifact '+str(ep/n)
    expected=integrity['files']['trajectory.h5'];assert (ep/'trajectory.h5').stat().st_size==expected['bytes'];assert ev['success'] in [True,False]
    record={'schema_version':cfg['schema_version'],'run_id':run_id,'task_id':task_id,'source_experiment_id':m['experiment_id'],'source_model_configuration_id':m['model_configuration_id'],'benchmark_task_id':m['task_id'],'suite':suite,'episode':m['episode'],'seed':m['seed'],'initial_state_index':m['initial_state_index'],'task_instruction':ins,'objects':entities,'scene_description':{'source_relative_path':str((ep/'semantic_initial_conditions.json').relative_to(source)),'json_pointer':'/phases/before_first_action/parsed_bddl_problem'},'simulation_conditions':{'randomization':m['randomization'],'initial_state_protocol':m['initial_state_protocol'],'task_horizon':m['task_horizon'],'semantic_phases':list(sem['phases']),'coordinate_system':phase.get('coordinate_system'),'randomization_parameters':phase.get('randomization_parameters')},'benchmark_outcome':{k:ev[k] for k in ['success','pass_fail','steps','termination_reason','error']},'safety_assessment':{'status':'not_assessed','violations':None,'reason':'No approved requirements or checking rules; benchmark failure is not a safety violation.'},'available_measurements':available,'evidence':{'trajectory':{'source_relative_path':str((ep/'trajectory.h5').relative_to(source)),'expected_sha256':expected['sha256'],'bytes':expected['bytes'],'integrity_status':'Producer manifest and current byte size checked; full HDF5 hash not independently recomputed'},'control_transitions':{'hdf5_group':'/transitions','step_id':'Recorded zero-based integer control-step index','step_count':ev['steps'],'after_action_frame_offset':offset},'task_definition':ref(td/'task.bddl'),'native_index':ref(ep/'simulator_index.json'),'environment_semantics':ref(ep/'semantic_initial_conditions.json'),'simulator_xml':ref(ep/'simulator.xml'),'evaluator':ref(ep/'evaluator_version.json'),'completion':ref(ep/'completion.json'),'integrity_manifest':ref(ep/'integrity_manifest.json')}}
    record['execution_files']=[{'name':f.name,'source_relative_path':str(f.relative_to(source)),'bytes':f.stat().st_size,'producer_integrity':integrity['files'].get(f.name)} for f in sorted(ep.iterdir()) if f.is_file()];runs.append(record);task_runs.append(run_id);instructions.append(ins);registrations.append(('run',run_id,{'task_id':task_id,'source_experiment_id':m['experiment_id'],'source_relative_episode':str(ep.relative_to(source))}))
    if ins['exact_mismatch']:instruction_diffs.append({'task_id':task_id,'run_id':run_id,'recorded_policy_instruction':recorded,'environment_bddl_language':bddl})
    if sample_scene is None:sample_scene=this_scene;sample_entities=entities;sample_measurements=available;sample_phase=phase;sample_evaluator=evaluator;sample_run=run_id
   assert len(task_runs)==50,'Unexpected episodes per task';assert len({x['text'] for x in instructions})==1,'Task has varying instructions; define run-specific task grouping before collection'
   facts={'task_instruction':instructions[0],'objects':{'reference_run_id':sample_run,'reference_native_bindings':sample_entities,'native_ids_must_be_read_per_run':True},'scene_description':sample_scene,'intended_interaction':{'instruction':instructions[0]['text'],'environment_objects_of_interest':sample_phase['objects_of_interest'],'environment_goal_predicates':sample_phase['goal_predicates'],'contact_plan':'Not explicitly specified; no allowed/prohibited contact policy inferred'},'scope':{'study_scope':cfg['study_scope'],'benchmark':'LIBERO','canonical_suite':tm['task_suite'],'benchmark_task_id':tm['task_id'],'task_name':tm['task_name'],'task_horizon':tm['task_horizon'],'randomization':tm['randomization'],'initial_state_protocol':tm['initial_state_protocol'],'checkpoint':tm['checkpoint'],'checkpoint_revision':tm['checkpoint_revision'],'task_success_is_not_safety':True},'available_measurements':{'reference_run_id':sample_run,**sample_measurements},'missing_information':sample_measurements['missing_information']}
   tasks.append({'schema_version':cfg['schema_version'],'task_id':task_id,'task_name':tm['task_name'],'suite':suite,'benchmark_task_id':tm['task_id'],'record_kind':'environment_facts','facts':facts,'environment_task_success_definition':{'goal_predicates':sample_evaluator['goal_predicates'],'runtime_library':sample_evaluator['runtime_library'],'runtime_library_version':sample_evaluator['runtime_library_version'],'evaluator_version':sample_evaluator['evaluator_version'],'success_signal':sample_evaluator['success_signal'],'source_relative_evaluator':str((td/'episode_000/evaluator_version.json').relative_to(source)),'source_relative_success_code':str((td/'episode_000/success_condition_source.py.txt').relative_to(source))},'run_ids':task_runs,'evidence':{'bddl':ref(td/'task.bddl'),'task_metadata':ref(td/'run_metadata.json'),'reference_run_id':sample_run},'proposed_requirement_ids':[]});print('COLLECTED',suite,tm['task_name'],len(task_runs),flush=True)
 assert len(tasks)==cfg['expected_task_count'] and len(runs)==cfg['expected_run_count'];assert len({x['task_id'] for x in tasks})==len(tasks) and len({x['run_id'] for x in runs})==len(runs)
 registry=Registry(project);registry.register_many(registrations)
 proposals=[]
 for name,records in [('tasks',tasks),('runs',runs),('proposed_requirements',proposals)]:save(project/'data'/(name+'.json'),{'schema_version':cfg['schema_version'],'records':records})
 for name in ['requirements','cases','claims','events','objections']:
  p=project/'data'/(name+'.json')
  if not p.exists():save(p,{'schema_version':cfg['schema_version'],'records':[]})
 if not (project/'config/approved_checkers.json').exists():save(project/'config/approved_checkers.json',{'schema_version':cfg['schema_version'],'records':[]})
 save(project/'reports/source_manifest.json',{'source_results':str(source),'small_file_hashes':sources,'large_arrays':'Retained in original HDF5; expected source integrity hashes referenced, not recomputed','collector_source_sha256':sha(Path(__file__))})
 save(project/'reports/instruction_mismatches.json',{'exact_mismatch_run_count':len(instruction_diffs),'exact_mismatch_task_count':len({x['task_id'] for x in instruction_diffs}),'records':instruction_diffs});save(project/'reports/prompt_verification.json',{'tokenizer_verified_against_checkpoint':True,'runs_checked':len(runs),'problem_runs':prompt_issues,'scope':'All recorded inference input_ids decoded and checked for exact recorded instruction substring; no model forwards.'})
 report={'current_stage':'execution_inventory_only','llm_called':False,'schema_version':cfg['schema_version'],'tasks':len(tasks),'runs':len(runs),'benchmark_success_percent':cfg['expected_success_percent'],'unique_task_ids':len(set(x['task_id'] for x in tasks)),'unique_run_ids':len(set(x['run_id'] for x in runs)),'proposed_requirements':len(proposals),'approved_requirements':0,'generated_safety_events':0,'safety_verdict':'not_assessed','instruction_mismatch_tasks':len({x['task_id'] for x in instruction_diffs}),'instruction_fallback_runs':sum(x['task_instruction']['fallback_used'] for x in runs),'prompt_verification_problem_runs':len(prompt_issues),'hdf5_root_annotation_matches':h5_annotation_hits,'elapsed_s':time.time()-start,'limitations':['Frame measurement inventory samples first/middle/final frames per run','No whole-array HDF5 checksum rehash or independent full video decode','Inventory only; requirements, cases, claims, safety events, objections, checkers and LLM components are outside this stage','Cases and claims need explicit evidence links and semantic review; argument revision does not certify a safer policy']};save(project/'reports/collection_report.json',report);print(json.dumps(report,indent=2))
if __name__=='__main__':
 ap=argparse.ArgumentParser();ap.add_argument('--project',type=Path,default=Path(__file__).resolve().parents[1]);a=ap.parse_args();collect(a.project)
